	/** 
	 * jumpstart the process by instantiating2 Policy
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		policyId = PolicyService.getPolicyInstance()
		.createPolicy( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		PolicyService.getPolicyInstance()
				.createPolicy( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.policySubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Policy : " + successValue.getPolicyId());
							  if (successValue.getPolicyId().equals(policyId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfPolicyList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Policy test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on policy consumed")
					);
			subscriber.policySubscribe( policyId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Policy : " + successValue.getPolicyId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfPolicyList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on policy for policyId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Policy. 
	 */
	protected Policy read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Policy" );

		Policy entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Policy with primary key" );
		msg.append( policyId );
		
		PolicyFetchOneSummary fetchOneSummary = new PolicyFetchOneSummary( policyId );

		try {
			entity = PolicyService.getPolicyInstance().getPolicy( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Policy " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Policy.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Policy." );

		StringBuilder msg = new StringBuilder( "Failed to update a Policy : " );        
		Policy entity = read();
		UpdatePolicyCommand command = generateUpdateCommand();
		command.setPolicyId(entity.getPolicyId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Policy." );

			// for use later on...
			policyId = entity.getPolicyId();

			PolicyService proxy = PolicyService.getPolicyInstance();  

			proxy.updatePolicy( command ).get();

			LOGGER.info( "-- Successfully saved Policy - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + policyId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Policy.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Policy." );

		Policy entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Policy with id " + policyId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Policy with id " + policyId );

			throw e;
		}

		try{
			PolicyService.getPolicyInstance().delete( new DeletePolicyCommand( entity.getPolicyId() ) ).get();
			LOGGER.info( "-- Successfully deleted Policy with id " + policyId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Policy with id " + policyId );

			throw e;
		}
	}

	/**
	 * get all Policys.
	 */
	protected List<Policy> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Policys:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Policy : " );        
		List<Policy> collection  = new ArrayList<>();

		try {
			// call the static get method on the PolicyService
			collection = PolicyService.getPolicyInstance().getAllPolicy();
			assertNotNull( collection, "An Empty collection of Policy was incorrectly returned.");
			
			// Now print out the values
			Policy entity = null;            
			Iterator<Policy> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getPolicyId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

